def sort_scores(xs):
    n = len(xs)
    for i in range(n):
        for j in range(n - 1 - i):
            if xs[j] > xs[j + 1]:
                xs[j], xs[j + 1] = xs[j + 1], xs[j]
    return xs


def count_known(ids):
    known = [k for k in range(0, 9000, 3)]
    hits = 0
    for x in ids:
        if x in known:
            hits += 1
    return hits


